import{_ as r,o as a,c as p,a2 as d}from"./chunks/framework.F7eQ-ohH.js";const e="/bzygq/assets/quesion_imgs_8da37e6da35b48838424550a2db9a0c9.BZboPxI-.png",o="/bzygq/assets/quesion_imgs_72da918b133e49d4833bc323c2535854.DJM_2VL8.png",m=JSON.parse('{"title":"什么是论证？","description":"","frontmatter":{},"headers":[],"relativePath":"行测/逻辑推理/4.逻辑判断/1.加强和削弱论证（可能性推理）.md","filePath":"行测/逻辑推理/4.逻辑判断/1.加强和削弱论证（可能性推理）.md","lastUpdated":1788883925000}'),n={name:"行测/逻辑推理/4.逻辑判断/1.加强和削弱论证（可能性推理）.md"};function s(i,t,l,h,_,g){return a(),p("div",null,[...t[0]||(t[0]=[d('<h1 id="什么是论证" tabindex="-1">什么是论证？ <a class="header-anchor" href="#什么是论证" aria-label="Permalink to &quot;什么是论证？&quot;">​</a></h1><p>论证是 <strong>用明确的依据（论据）支撑核心观点（论点）的逻辑过程</strong>，本质是连接 “论据” 与 “论点” 的推理链条，且需依赖未明确表述但必需的隐含前提，才能形成完整、可信的逻辑闭环。</p><p><img src="'+e+'" alt=""></p><p>一个完整的论证过程应该包含论点、论据、论证过程和前提，用公式来表达的话就是：论证 = 论点+论据+论证过程。比如我们从“小明帮助同学”得出“小明是个好学生”，这个论证就包含了很多隐含的前提，比如“小明帮助同学”这件事是真实存在的前提是“小明是个人”。</p><ol><li><strong>论点</strong>：最终要证明的核心观点（如 “小明是个好学生”）；</li><li><strong>论据</strong>：支撑论点的具体依据、事实或理由（如 “小明帮助同学”）；</li><li><strong>论证过程</strong>：连接论据与论点的逻辑桥梁（如从 “小明帮助同学” 推导出 “小明是个好学生” 的推理逻辑）；</li><li><strong>隐含前提</strong>：论证成立必需但未直接说明的条件（如 “帮助他人是评判‘好学生’的有效维度”“小明帮助同学的行为真实存在”）。</li></ol><p>简单来说，论证的核心是 “用理由证明观点” 的完整逻辑链，缺任意一个要素（如论据不真实、逻辑桥梁断裂、隐含前提不成立），都会导致论证可信度下降。</p><h1 id="什么是加强削弱论证" tabindex="-1">什么是加强削弱论证？ <a class="header-anchor" href="#什么是加强削弱论证" aria-label="Permalink to &quot;什么是加强削弱论证？&quot;">​</a></h1><p>加强 / 削弱论证的本质，是针对 “用论据支撑论点” 的逻辑过程，通过补充信息来调整其可信程度 要理解这一概念，我们先从一个典型基础论证入手：​</p><ul><li><strong>论据</strong>：小明帮助同学</li><li><strong>论点</strong>：小明是个好学生</li></ul><p>论证的本质是 “用论据支撑论点” 的逻辑过程，而<strong>加强论证</strong>就是通过补充信息，提升 “论据→论点” 的可信程度；<strong>削弱论证</strong>则是通过补充信息，降低这一逻辑的可信程度。</p><ul><li>加强示例：“乐于帮助他人是评判‘好学生’的核心标准”（直接强化论据与论点的关联，让结论更成立）；</li><li>削弱示例：“小明帮助同学时，实则偷走了对方的水杯”（补充反向信息，瓦解 “帮助同学” 与 “好学生” 的正向关联）。</li></ul><p>简单来说，加强是 “帮论证站得住脚”，削弱是 “让论证站不住脚”，二者均不脱离 “论据→论点” 的核心逻辑链。</p><h1 id="加强削弱解题方法" tabindex="-1">加强削弱解题方法 <a class="header-anchor" href="#加强削弱解题方法" aria-label="Permalink to &quot;加强削弱解题方法&quot;">​</a></h1><p>加强削弱题的本质是 <strong>“针对论证逻辑链（论据→论点），通过选项调整其可信程度”</strong>，解题关键是 “不脱离逻辑链、不被无关信息干扰”，核心方法仍遵循 “找论点→筛选项→比强弱” 三步法：</p><p><img src="'+o+'" alt=""></p><ol><li><strong>找论点</strong>：论点是论证的核心观点，通常出现在 “表明、发现、声称、结论、因此、所以” 等关联词后，也常位于段首（总起）或段尾（总结）；</li><li><strong>筛选项</strong>：先排除 “无关项”（与论点、论据无逻辑关联）和 “反向项”（与题干要求的 “加强 / 削弱” 相悖），保留直接针对论证逻辑的核心候选项；</li><li><strong>比强弱</strong>：核心原则是 “直接＞间接”—— 针对论点 / 论证过程的选项，强度高于仅针对论据的选项。</li></ol><p>比如说一个加强题目，我们找到论点之后，先看看选项，把那些明显是削弱项的排除，然后把无关项排除，这时候可能还剩下两个都能加强，再比较二者强弱即可。</p><h1 id="常见加强削弱论证方法" tabindex="-1">常见加强削弱论证方法 <a class="header-anchor" href="#常见加强削弱论证方法" aria-label="Permalink to &quot;常见加强削弱论证方法&quot;">​</a></h1><h2 id="加强论证的常见方式" tabindex="-1">加强论证的常见方式 <a class="header-anchor" href="#加强论证的常见方式" aria-label="Permalink to &quot;加强论证的常见方式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>定义</th><th>示例</th></tr></thead><tbody><tr><td>直接肯定论点</td><td>直接支持核心观点，无需额外推导</td><td>小明确实是品学兼优的好学生</td></tr><tr><td>补充正向论据</td><td>增加新的依据支撑论点</td><td>小明除了帮助同学，还经常主动协助老师处理事务</td></tr><tr><td>强化原有论据</td><td>确认原有论据的真实性 / 有效性</td><td>班上多名同学均证实曾看到小明主动帮助同学</td></tr><tr><td>搭桥（强化论证过程）</td><td>明确论据与论点的必然关联</td><td>乐于帮助他人的学生，本质上都是好学生</td></tr><tr><td>明确隐含前提</td><td>点出论证成立的必需条件</td><td>当时同学确实处于需要帮助的状态，小明的帮助具有实际意义</td></tr></tbody></table><h2 id="削弱论证的常见方式" tabindex="-1">削弱论证的常见方式 <a class="header-anchor" href="#削弱论证的常见方式" aria-label="Permalink to &quot;削弱论证的常见方式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>定义</th><th>示例</th></tr></thead><tbody><tr><td>直接否定论点</td><td>直接反驳核心观点</td><td>小明并非好学生，他经常违反校规、欺负同学</td></tr><tr><td>补充反向论据</td><td>增加与论点相悖的依据</td><td>小明帮助同学时，偷走了对方的水杯</td></tr><tr><td>弱化原有论据</td><td>质疑原有论据的真实性 / 有效性</td><td>没有任何同学亲眼看到小明帮助同学，其说法缺乏实证</td></tr><tr><td>拆桥（削弱论证过程）</td><td>切断论据与论点的逻辑关联</td><td>是否帮助同学，并非评判 “好学生” 的标准</td></tr><tr><td>否定隐含前提</td><td>指出论证成立的必需条件不成立</td><td>当时同学根本不需要帮助，小明的所谓 “帮助” 是多余行为</td></tr></tbody></table><h1 id="真题" tabindex="-1">真题 <a class="header-anchor" href="#真题" aria-label="Permalink to &quot;真题&quot;">​</a></h1><p>例1：2018年全国高校毕业生将达820万，再创历史新高。眼下为了“抢”人才，不少城市纷纷出台引才新政。媒体进行的一项调查显示：在回答“你希望就业的城市”这一问题时，六成受访者选择二线城市，三成受访者选择一线城市，仅一成选择三四线城市。这主要基于生活成本、就业机会与发展空间的综合考量。80.53%的受访者认为房价等生活成本是主要考虑因素。换个更直白的说法，<strong>就是一线城市居之不易，于是大学生就业“首选二线城市”</strong>，下列各项如果为真，最能支持上述观点的是：（<strong>直接肯定论点</strong>）</p><p>A.一线城市经济活力强，具有更多的发展机会</p><p>B.综合考虑生活成本与发展机会，二线城市更受毕业生青睐</p><p>C.就目前情况来看，三四线城市经济活力不足，发展机会有限</p><p>D.高房价令毕业生对一线城市望而生畏</p><p>解析：直接加强原有论点，在现实生活中是没有说服力的，只不过把话再说一遍而已，但是注意，在考试中人家问的是“以下哪项如果为真”，对观点的重复为真，那么观点必然为真，所以直接加强论点是种非常强的加强方式。这道题目，答案选B，因为B是对观点的重复，B为真，上述观点必然为真。</p><p>例2：（论据）<strong>当一个人处于压力下的时候，（论点）他更可能得病</strong>。下列说法最能支持上述结论的是（ ）（<strong>增加论据</strong>）</p><p>A.研究显示，医院或诊所是一个有压力的环境</p><p>B.许多企业反映职员在感到工作压力增大时，缺勤明显减少</p><p>C.在放假期间，大学医院的就诊人数显著增加</p><p>D.在考试期间，大学医院的就诊人数显著增加</p><p>解析：这道题题干只有论点，这时候给它一个论据作为支撑，就是很强的加强，很明显，选项里面能加强上述观点的只有D。</p><p>例3：据某知名房产中介机构统计，2010年9月份第二周全国十大城市的商品房成交量总体呈上涨趋势，并且与8月份第二周相比上周幅度更明显。如果没有其他因素抑制，按照这种趋势发展，9月份或将创新政以来成交量最高水平，虽然现在还不能明确楼市完全回暖，（论点）但未来楼价调控的压力还是很大的。下列最有可能是上述论证前提假设的是：（<strong>搭桥</strong> ）</p><p>A.炒房者将大量资金投入楼市</p><p>B.国家对楼价的调控手段不足</p><p>C.消费者对房子的购买热情没有减退</p><p>D.楼市成交量的增长会带动楼价的上涨</p><p>解析：在做论证题目的时候，我们经常会碰到这样一种题目——结论得出的很突兀，好像论据和论点之间缺点什么，一般这种情况直接考虑搭桥，即在论点和论据之间建立联系。这道题先是提到了成交量创最高水平，于是得出结论说楼价调控压力很大，这就很突兀，所以我们需要一个选项能在成交量和楼价之间建立联系的选项，所以答案选D。有了D这个选项之后，结论的得出，就是自然而然的事情了。这就是所谓的搭桥。搭桥是加强类题目中最为常见的一种加强方式，也是非常强的一种加强方式，见了直接选，基本是没什么问题的（具体我们后面会有更加细致的分析）。</p><p>例4：某公司为度过暂时的经济危机决定减少业务员的数量。公司董事会计划首先解雇效率较低的业务员，而不是简单按照业务员业务量多少决定解雇哪些业务员。以下哪项是公司董事会做出这个决定的前提？（ ）</p><p>A.业务员的报酬是根据业务量的多少决定的</p><p>B.最具有业务经验的业务员是最好的业务员</p><p>C.一个业务员的效率不会与另一个业务员的相同</p><p>D.董事会有能比较准确地判定业务员效率的方法</p><p>解析：凡是碰到让我们找“前提”的论证题目，都可以使用“否定代入法”，也就是看看缺了这个条件还行不行。公司既然想按照效率决定解雇谁不解雇谁，必须能够比较准确地判断业务员效率的方法才行，如果没有这个方法，不能准确地判定业务员的效率，那么就无法施行题干中提到的危机解决办法。所以D是董事会作出这个决定必不可少的前提。C不是必要前提，因为两个业务员效率相同，都高就都留任，都低都解雇，只要别所有的业务员效率都一样就行。</p><p>例5：某研究调查了数千名被试的睡眠情况与健康状况，结果发现，从中年至老年（50岁至70岁间）一直处于较短睡眠模式（即每晚睡眠时长少于6小时）的人，失智风险会增加30%。研究者呼吁，中老年人适当增加睡眠时长，可以预防失智的发生。以下陈述如果为真，哪项最能质疑研究者的观点？（<strong>直接否定论点</strong>）</p><p>A.老年人每日睡眠时间过长不仅会有疲劳感，还会记忆力降低，精力不集中</p><p>B.随着年龄的增加，身体的细胞也慢慢衰老，这就导致睡眠时间开始变短</p><p>C.心血管代谢问题和精神疾患等都是失智的重要风险因素</p><p>D.失智是一种因脑部疾病所导致的渐进性认知功能退化，跟睡眠时长无关</p><p>解析：直接否定论点，毫无疑问是最强的削弱方式。D是直接否定论点，当选。</p><p>例6：“<a href="https://zhida.zhihu.com/search?content_id=176654652&amp;content_type=Article&amp;match_order=1&amp;q=%E4%B8%9C%E8%83%A1%E6%9E%97&amp;zhida_source=entity" target="_blank" rel="noreferrer">东胡林</a>人”遗址是<a href="https://zhida.zhihu.com/search?content_id=176654652&amp;content_type=Article&amp;match_order=1&amp;q=%E6%96%B0%E7%9F%B3%E5%99%A8%E6%97%B6%E4%BB%A3&amp;zhida_source=entity" target="_blank" rel="noreferrer">新石器时代</a>早期的人类文化遗址，在遗址中发现的人骨化石经鉴定属两个成年男性个体和一个少年女性个体。在少女遗骸的颈部位置有用小螺壳串制的项链，腕部佩戴有牛肋骨制成的骨镯。这说明在新石器时代早期，人类的审美意识己开始萌动。以下哪项如果为真，最能削弱上述判断？（ ）（<strong>拆桥</strong>）</p><p>A.新石器时代的饰品通常是石器。</p><p>B.出土的项链和骨镯都十分粗糙。</p><p>C.项链和骨镯的作用主要是表示社会地位。</p><p>D.两个成年男性遗骸的颈部有更大的项链。</p><p>解析：C表示项链和骨镯是表示社会地位的，和审美之间未必存在什么联系，所以直接削弱了论点和论据之间的联系，属于典型拆桥。</p><p>拆桥这种削弱方式不能说弱，但它不是最强的（和直接否定论点、否定前提比弱了些），因为拆桥只能说明论据不能证明论点，但是论点是对是错，还是不一定的。比如“扶老奶奶过马路和是不是好人之间没有必然联系”，但是“小明是个好人”依然可能成立。我们后续会对这个问题做出更细致的分析。</p>',60)])])}const b=r(n,[["render",s]]);export{m as __pageData,b as default};
